 * (`session-view-path-deleted`). Composes at rest, with no entrance motion
 * (KAN-575 fix round 2, `no-entrance-motion-on-drawer-rows-and-settings`).
 */
@Composable
private fun BodyUnitsSetting(
    bodyUnits: BodyUnitState,
    profile: Profile,
    scope: CoroutineScope,
) {
    val colors = BroadsheetTheme.colors
    Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.fillMaxWidth()) {
        Column {
            Text("Body units", style = BroadsheetTheme.type.body, color = colors.text)
            Text("Your weight and height", style = BroadsheetTheme.type.caption, color = colors.neutral700)
        }
        Spacer(modifier = Modifier.weight(1f))
        BroadsheetInlineSegmentedControl(
            options = BodyUnit.entries,
            selected = bodyUnits.bodyUnit,
            label = { unit -> if (unit == BodyUnit.METRIC) "kg · cm" else "lb · ft in" },
            enabled = true,
            testTag = "settings_body_units",
            optionTag = { "settings_body_units_${it.name}" },
            onSelect = { unit -> scope.launch { bodyUnits.choose(unit, profile) } },
        )
    }
}

