            val writeGateA = CompletableDeferred<Unit>()
            api.beforeUpdatePreferences = { unit -> if (unit == WeightUnit.LBS) writeGateA.await() }
            val writeA = launch { state.chooseUnit(WeightUnit.LBS) }
            runCurrent()

